 const adapter={kind:f.adapter.kind,async read(...args:Parameters<typeof f.adapter.read>){if(fault==='deadline')f.clock.set(o.expires_at);if(fault==='pause'||fault==='stop')control(fault);return f.adapter.read(...args);}},transport={...f.transport,async exchange(...args:Parameters<typeof f.transport.exchange>){const response=await f.transport.exchange(...args);if(fault==='after_response')control('stop');return response;}};
 await assert.rejects(()=>collectPrivateResearch(f.company,f.result.scope.scopeId,f.company.observedInvestment.request('AAPL',o.session,false),undefined,{adapter,transport},binding));assert.equal(f.calls(),fault==='after_response'?1:0);assert.equal(f.store.all('SELECT * FROM observed_financial_evidence').length,0);assert.equal(f.store.all("SELECT * FROM investment_market_records WHERE kind='price'").length,0);if(fault!=='rollback'){const counts=f.journal.counts(f.input.policy.authorityId,f.clock.now());assert.equal(counts.collections.length,1);assert.equal(counts.collections[0]!.state,fault==='after_response'?'unknown':'settled');}
