test('schema24 to25 preserves populated journal, employee receipts, rowids, FK/indexes and spent external authority',t=>{const f=runningFiniteFixture(t);t.after(f.close);f.session(0);const x=f.claim();f.contribute(x);f.finish(x);const head=f.authority.journal.counts(f.policy.authorityId,f.clock.now()),path=join(f.dir,'legacy24.sqlite');f.store.db.exec(`VACUUM INTO '${path.replaceAll("'","''")}'`);const legacy=new DatabaseSync(path);removeEmptyObservedMigration(legacy);const tables=(legacy.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name").all() as {name:string}[]).map(r=>r.name),before=Object.fromEntries(tables.map(name=>[name,legacy.prepare('SELECT rowid,* FROM '+name+' ORDER BY rowid').all()]));legacy.close();for(let pass=0;pass<2;pass++){const store=new Store(path);try{for(const name of tables)assert.deepEqual(store.all('SELECT rowid,* FROM '+name+(name==='schema_migrations'?' WHERE version<=24':'')+' ORDER BY rowid'),before[name],name);assert.deepEqual(store.all('PRAGMA foreign_key_check'),[]);assert.equal(store.get<{integrity_check:string}>('PRAGMA integrity_check')!.integrity_check,'ok');assert.equal(store.all('SELECT * FROM observed_investment_runs').length,0);assert.throws(()=>store.run("UPDATE investment_journal SET journal_hash='changed'"),/immutable/);assert.throws(()=>store.run("DELETE FROM investment_team_scopes"),/retained|immutable|FOREIGN KEY/);}finally{store.close();}}assert.deepEqual(f.authority.journal.counts(f.policy.authorityId,f.clock.now()),head);});

test('failed observed approval can be cancelled and renewed without resetting capital or history',t=>{const f=setup(t);t.after(f.close);const c=f.company,stop=(id:string)=>c.investmentLoop.control({loopId:id,action:'stop',digest:null,orderId:null,receiptId:randomUUID()});stop(f.result.loop.loopId);const prefix=c.observedInvestment.history(f.result.runId).ledger,renew=()=>{const p=c.observedInvestment.preview({...f.input,runId:f.result.runId,policy:{...f.input.policy,authorityId:'finite_'+randomUUID()}});return c.observedInvestment.consent({previewId:p.previewId,digest:p.digest,receiptId:randomUUID()});};const rejected=renew();assert.throws(()=>c.finiteHQ.approve(rejected.scope.scopeId,f.account,{ownerId:'human',receiptHash:hash('fixture'),approvedAt:'invalid'},{authorityId:rejected.scope.envelope.executionPolicy.authorityId,runId:f.result.runId,accountFingerprint:f.account.accountFingerprint,ownerId:'human',confirmedAt:f.clock.now(),reloadOff:true,evidenceHash:hash('fixture')}));assert.equal(c.finiteHQ.approved(rejected.scope.scopeId),false);stop(rejected.loop.loopId);const next=renew();assert.equal(next.runId,f.result.runId);assert.equal(c.observedInvestment.history(next.runId).ledger.portfolio.cash,prefix.portfolio.cash);assert.equal(f.store.all("SELECT * FROM investment_journal WHERE run_id=? AND json_extract(payload,'$.command.type')='initialize'",next.runId).length,1);assert.equal(c.finiteHQ.inspect(next.scope.scopeId)?.approved,false);assert.equal(f.journal.counts(f.input.policy.authorityId,f.clock.now()).run,0);});

test('scope covers ordinary and early-close final order cleanup',t=>{const f=setup(t);t.after(f.close);const saved=f.company.observedInvestment.scopeConfiguration(f.result.scope.scopeId);assert.ok(saved.expiresAt>f.company.investmentLoop.occurrences(f.company.investmentLoop.get(f.result.loop.loopId)).filter(o=>o.stage==='expire').at(-1)!.due_at);f.clock.set('2026-11-26T21:00:00.000Z');const p=f.company.observedInvestment.preview({...f.input,policy:{...f.input.policy,authorityId:'finite_'+randomUUID()},sessions:['2026-11-27']});assert.ok(p.expiresAt>'2026-11-28T00:30:00.000Z');});

function observedPublisher(current:()=>Company,f:ReturnType<typeof setup>,description:PublicationDescription){
 const key=generateKeyPairSync('ed25519'),keys=new ServiceKeyRing(new Map([['key',{key:key.privateKey,notBefore:0,notAfter:2000000000,enabled:true}]])),destination={id:'site',title:'Fixture',origin:'https://example.invalid',publisherId:'pub',keyId:'key',generation:'1'},events:any[]=[],receipts=new Map<string,any>(),nonces=new Set<string>();let generation='1',scope:any;
 const response=(v:unknown)=>({status:200,contentType:'application/json',bytes:Buffer.from(canonicalJson(v))});
 const transport={send:async(_d:any,m:any)=>{
  if(m.path.endsWith('/status')){const receipt=[...receipts.values()].at(-1)!,sample=JSON.parse(readFileSync('contracts/investment/v1/responses.json','utf8')).examples.PublicStatus;return response({...sample,experimentId:receipt.experimentId,runId:receipt.runId,watermark:receipt.watermark});}
const checked=verifySignedRequest(m,{authority:'example.invalid',generation,keyId:'key',publicKey:key.publicKey,enabled:true,notBefore:0,notAfter:2000000000,now:Math.floor(Date.parse(f.clock.now())/1000),usedNonces:nonces,targets:new Set([`${m.method} ${m.path}`])});nonces.add(checked.nonceKey);

  if(m.method==='GET')return response(receipts.get(m.path.split('/').at(-1)!));
  assert.notEqual(m.method,'PUT','events-only standing authority never uploads content');const value=parseJson(m.body) as any;if(m.path.endsWith('/heartbeat'))return response({schemaVersion:'1.0',heartbeatId:value.heartbeatId,receivedAt:f.clock.now()});
  const batch=validate<any>('EventBatch',value);checkPublicationBatch(m.body,batch.batchId,{experimentId:scope.experimentId,runId:scope.runId,now:f.clock.now(),scope,history:events,content:new Map(),receipts:new Map()});assert.doesNotMatch(m.body.toString(),/PRIVATE_.*_SENTINEL/);events.push(...batch.events);const ledger=events.filter(e=>e.type==='paper.ledger_transaction').at(-1),last=events.at(-1),receipt={schemaVersion:'1.0',batchId:batch.batchId,experimentId:batch.experimentId,runId:batch.runId,bodyDigest:sha256(m.body),receiptId:'fixture-receipt',receivedAt:f.clock.now(),acceptedIds:batch.events.map((e:any)=>e.eventId),duplicateIds:[],receiverCursor:'fixture-cursor',watermark:{journalSequence:ledger?.payload.journalSequence??null,journalHash:ledger?.payload.journalHash??null,sourceSequence:last.sourceSequence,sourceGaps:false}};receipts.set(batch.batchId,receipt);return response(receipt);
 }};
 const make=()=>{const source=new ObservedTeamPublicationSource('authored','Authored',current().store,f.clock,'observed-paper-owner',f.result.runId,description,true);return new PublicationService(current().store,{sources:[source],destinations:[destination],clock:f.clock,keys,transport,autoObserved:true});};
 let service=make();const envelope={sourceId:'authored',destinationId:'site',audience:'public',futureFinancial:true,futureSummaries:true,participants:f.input.participants.map(p=>p.workerId),eventTypes:['run.published','team.published','run.status','discussion.opened','discussion.contribution','decision.published','paper.order','paper.ledger_transaction','portfolio.snapshot','market.action','instrument.updated'],contentTypes:[],expiresAt:'2026-10-25T00:00:00.000Z',maxAttempts:1000,maxBytes:8388608,maxQueueBytes:8388608,maxAgeSeconds:86400,writesPerMinute:60};
 const p=service.preview(envelope),channelId=service.consent({previewId:p.id,digest:p.digest}).channelId,first=p.material.events[0]!.event;scope=validate<any>('PublisherScope',{publisherId:'pub',keyId:'key',experimentId:first.experimentId,runId:first.runId,eventTypes:envelope.eventTypes,contentTypes:['application/json'],publicationPolicyVersion:first.publicationPolicyVersion,expiresAt:envelope.expiresAt,enabled:true,generation,writesPerMinute:60,bytesPerDay:envelope.maxBytes});assert.deepEqual(p.envelope.contentTypes,[]);
 const strictSource=new ObservedTeamPublicationSource('authored','Authored',current().store,f.clock,'observed-paper-owner',f.result.runId,description,true),strict=new PublicationService(current().store,{sources:[strictSource],destinations:[{...destination,id:'site-strict'}],clock:f.clock}),sp=strict.preview({...envelope,destinationId:'site-strict',futureSummaries:false,contentTypes:['application/json']}),sg=strict.consent({previewId:sp.id,digest:sp.digest});
 return {get service(){return service;},envelope,events,channelId,denyUnapprovedSummaries(){assert.throws(()=>strict.capture({channelId:sg.channelId}),/new_derivative_approval_required/);},async drain(){await new Promise<void>(resolve=>service.progress(resolve));assert.equal(service.health(channelId).captureError,null);for(let n=0;n<100&&service.health(channelId).pending;n++){await service.deliver({channelId});if(n===55)f.clock.set(new Date(Date.parse(f.clock.now())+61000).toISOString());}assert.equal(service.health(channelId).pending,0,JSON.stringify(service.health(channelId)));},async restart(){service=make();assert.equal(service.health(channelId).restoreRequired,true);await assert.rejects(service.deliver({channelId}),/restore_reconciliation_required/);generation=String(Number(generation)+1);service.control({channelId,action:'generation',generation,keyId:null});const p=service.preview(envelope);service.consent({previewId:p.id,digest:p.digest});scope.generation=generation;await service.reconcile({channelId});assert.equal(service.health(channelId).restoreRequired,false);}};
}

test('new observed book can begin on a later selected session without inventing an omitted benchmark opening',t=>{const f=setup(t);t.after(f.close);const p=f.company.observedInvestment.preview({...f.input,sessions:['2026-10-21'],policy:{...f.input.policy,authorityId:'finite_'+randomUUID()}}),r=f.company.observedInvestment.consent({previewId:p.previewId,digest:p.digest,receiptId:randomUUID()});assert.equal(r.configuration.observedPolicy.initialSession,'2026-10-21');assert.equal(f.company.observedInvestment.history(r.runId).ledger.benchmarkNextOpen,'2026-10-21');assert.equal(f.runtime.calls.length,0);});

function fixturePublicationDescription(f:ReturnType<typeof setup>):PublicationDescription{return {title:'Authored observed-format fixture',purpose:'Offline integration',objective:'Never live evidence',openingFieldDefinition:'Authored raw daily OPEN',attribution:'Authored fixture',rightsEvidence:['https://example.invalid/fixture'],limitations:['No real data or genuine AI'],cycleExecutionBudget:6,dailyExecutionBudget:6,runExecutionBudget:16,heartbeatSeconds:900,staleSeconds:2700,maxOutboxAgeSeconds:86400,maxOutboxBytes:8388608,dataDelaySeconds:0,workers:Object.fromEntries(f.input.participants.map(p=>[p.workerId,{name:p.name,role:'Fixture employee',responsibilities:[p.responsibility],status:'unavailable'}])),instrumentClassification:Object.fromEntries([...f.input.instruments,f.input.benchmark].map(i=>[i.id,'Authored classification'])),actionSources:{},artifacts:[]};}

test('standing events-only grant retains empty upload authority and rejects an injected JSON job before transmission',async t=>{const f=setup(t);t.after(f.close);const p=observedPublisher(()=>f.company,f,fixturePublicationDescription(f));await p.drain();assert.equal(f.store.all("SELECT * FROM investment_public_jobs WHERE kind='content'").length,0);const channel=f.store.get<any>('SELECT * FROM investment_public_channels WHERE id=?',p.channelId)!,grant=p.service.health(p.channelId).grantId!,before=p.events.length,bytes=Buffer.from('{}');(p.service as any).addJob(channel,grant,'content',bytes,`/api/experiments/v1/experiments/${channel.experiment_id}/runs/${channel.run_id}/content/${sha256(bytes)}`,'application/json');await assert.rejects(p.service.deliver({channelId:p.channelId}),/content_scope_denied/);assert.equal(p.events.length,before);});

