test('settled collection with lost local result remains held across restart without re-fetch',async t=>{
 const f=setup(t);let c=f.company,journal=f.journal;let d=new Dispatcher(c,f.runtime);
 t.after(async()=>{await d.stop();c.finiteHQ.close();c.store.close();rmSync(f.dir,{recursive:true,force:true});});
 c.observedInvestment.fixture={adapter:f.adapter,transport:f.transport};
 const original=c.store.run.bind(c.store);c.store.run=((sql:string,...args:any[])=>{if(sql.startsWith('INSERT INTO observed_collection_results'))throw Error('authored crash after independent settlement');return original(sql,...args);}) as typeof c.store.run;
 c.investmentLoop.control({loopId:f.result.loop.loopId,action:'start',digest:f.result.loop.digest,receiptId:randomUUID(),orderId:null});
 const first=c.investmentLoop.occurrences(c.investmentLoop.get(f.result.loop.loopId)).find(o=>o.stage==='collect_research')!;f.clock.set(first.due_at);d.start();d.kick();await waitUntil(()=>c.investmentLoop.get(f.result.loop.loopId).state==='blocked');
 assert.equal(f.calls(),1);assert.equal(c.store.all('SELECT * FROM observed_collection_results').length,0);assert.equal(journal.counts(f.input.policy.authorityId,f.clock.now()).collections[0]!.state,'settled');
 await d.stop();const path=journal.path,custody=journal.custodyPath;c.finiteHQ.close();c.store.close();c=new Company(new Store(join(f.dir,'company.sqlite')),f.dir,process.cwd(),'fake');c.mandates.clock={now:()=>Date.parse(f.clock.now())};journal=new FiniteJournal(path,custody);c.finiteHQ.attach(journal);c.observedInvestment.fixture={adapter:f.adapter,transport:f.transport};d=new Dispatcher(c,f.runtime);d.start();d.kick();await d.stop();assert.equal(c.investmentLoop.get(f.result.loop.loopId).state,'blocked');assert.equal(f.calls(),1);assert.equal(f.runtime.calls.length,0);
});
